      "codeSnippet": "export const sendEmail = async ({ to, subject, html, text }) => {\n  const mailOptions = {\n    from: `\"${process.env.APP_NAME}\" <${process.env.EMAIL_FROM}>`,\n    to,\n    subject,\n    text, // Plaintext version for spam filters & accessibility\n    html, // Rich HTML version\n  };\n\n  const info = await transporter.sendMail(mailOptions);\n  console.log(\"Email dispatched successfully. MessageID:\", info.messageId);\n  return info;\n};"
